package pro.erez.interstice.test;
import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.vehicle.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.neoforged.neoforge.gametest.*;
import pro.erez.interstice.Interstice;
import pro.erez.interstice.ocean.*;
@GameTestHolder("interstice_toxin_waves") @PrefixGameTestTemplate(false)
public final class LowerToxinWaveGameTests {
    static Boat boat(GameTestHelper h,int x,int z,Boat.Type type){var b=new Boat(h.getLevel(),h.absolutePos(new BlockPos(x,3,z)).getX()+.5,h.absolutePos(new BlockPos(x,3,z)).getY()+.6,h.absolutePos(new BlockPos(x,3,z)).getZ()+.5);b.setVariant(type);h.getLevel().addFreshEntity(b);return b;}
    static void pool(GameTestHelper h){for(int x=0;x<30;x++)for(int z=0;z<30;z++){h.setBlock(new BlockPos(x,1,z),Blocks.STONE);h.setBlock(new BlockPos(x,2,z),Interstice.HEAVY_BLOCK.get());h.setBlock(new BlockPos(x,3,z),Interstice.HEAVY_BLOCK.get());for(int y=4;y<=10;y++)h.setBlock(new BlockPos(x,y,z),Blocks.AIR);}}
    @GameTest(template="empty",timeoutTicks=20,batch="wave_math") public static void boundedPeriodicFieldAndAnalyticDerivatives(GameTestHelper h){
        for(int i=0;i<3000;i++){double x=i*17.31-20000,z=i*31.17-19000,t=i*.77;var s=LowerToxinSurface.wave(x,z,t,35,1);h.assertTrue(Math.abs(s.height()-35)<=.42000001,"Wave amplitude escaped bound");var p=LowerToxinSurface.wave(x+4096,z-4096,t+1920,35,1);h.assertTrue(Math.abs(p.height()-s.height())<1e-9,"World/time wrap discontinuity");double d=(LowerToxinSurface.wave(x+.001,z,t,35,1).height()-LowerToxinSurface.wave(x-.001,z,t,35,1).height())/.002;h.assertTrue(Math.abs(d-s.dx())<1e-8,"Incorrect wave slope");var flat=LowerToxinSurface.wave(x,z,t,35,0);h.assertTrue(flat.height()==35&&flat.velocity()==0,"Bank mask failed");}h.succeed();
    }
    @GameTest(template="empty",timeoutTicks=240,batch="boat_all") public static void everyMaterialFloatsBeforeDissolvingAtTwoHundredContactTicks(GameTestHelper h){pool(h);var boats=new ArrayList<Boat>();int i=0;for(var type:Boat.Type.values()){boats.add(boat(h,3+(i%3)*4,3+(i/3)*4,type));i++;}h.runAtTickTime(120,()->{for(var b:boats)h.assertTrue(b.isAlive()&&ToxinBoats.exposure(b)>100&&Math.abs(b.getY()-(h.absolutePos(new BlockPos(0,3,0)).getY()+8.0/9-.18))<.15,"Boat did not float during corrosion: "+b.getVariant()+" tick="+b.tickCount+" exposure="+ToxinBoats.exposure(b)+" pos="+b.position()+" surface="+ToxinBoats.surface(b));});h.runAtTickTime(220,()->{for(var b:boats)h.assertTrue(!b.isAlive()&&ToxinBoats.exposure(b)==200,"Wrong corrosion boundary "+b.getVariant()+" "+ToxinBoats.exposure(b));h.succeed();});}
    @GameTest(template="empty",timeoutTicks=130,batch="boat_save") public static void dryTimeDoesNotRepairAndNbtAndItemPreserveExposure(GameTestHelper h){pool(h);var b=boat(h,4,4,Boat.Type.OAK);h.runAtTickTime(50,()->{h.assertTrue(ToxinBoats.exposure(b)>40,"No exposure: ticks="+b.tickCount+" pos="+b.position()+" surface="+ToxinBoats.surface(b)+" below="+h.getLevel().getFluidState(b.blockPosition()));int old=ToxinBoats.exposure(b);b.setPos(b.getX(),b.getY()+6,b.getZ());b.setNoGravity(true);b.setDeltaMovement(0,0,0);var n=new CompoundTag();b.saveWithoutId(n);var copy=new Boat(EntityType.BOAT,h.getLevel());copy.load(n);h.assertTrue(ToxinBoats.exposure(copy)==old,"NBT reset exposure");var stack=new ItemStack(Items.OAK_BOAT);ToxinBoats.saveItem(b,stack);var placed=new Boat(EntityType.BOAT,h.getLevel());ToxinBoats.loadItem(placed,stack);h.assertTrue(ToxinBoats.exposure(placed)==old,"Item reset exposure");h.runAfterDelay(40,()->{h.assertTrue(ToxinBoats.exposure(b)==old&&b.isAlive(),"Dry timer advanced or repaired");b.discard();h.succeed();});});}
    @GameTest(template="empty",timeoutTicks=240,batch="boat_chest") public static void chestAndPassengerSurviveDissolutionWithoutDuplicateHull(GameTestHelper h){pool(h);var pos=h.absolutePos(new BlockPos(7,3,7));var b=new ChestBoat(h.getLevel(),pos.getX()+.5,pos.getY()+.6,pos.getZ()+.5);b.setItem(0,new ItemStack(Items.DIAMOND,7));h.getLevel().addFreshEntity(b);var pig=EntityType.PIG.create(h.getLevel());pig.setNoAi(true);pig.moveTo(b.position());h.getLevel().addFreshEntity(pig);pig.startRiding(b,true);h.runAtTickTime(220,()->{h.assertTrue(!b.isAlive()&&pig.isAlive()&&pig.getVehicle()==null,"Passenger retained destroyed vehicle");int diamonds=0,hulls=0;for(var e:h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,b.getBoundingBox().inflate(5))){if(e.getItem().is(Items.DIAMOND))diamonds+=e.getItem().getCount();if(e.getItem().is(Items.OAK_CHEST_BOAT)||e.getItem().is(Items.OAK_BOAT))hulls+=e.getItem().getCount();}h.assertTrue(diamonds==7&&hulls==0,"Dissolution duplicated/lost inventory or returned hull: "+diamonds+"/"+hulls);h.succeed();});}
    @GameTest(template="empty",timeoutTicks=80,batch="boat_water") public static void ordinaryWaterDoesNotCorrode(GameTestHelper h){for(int x=0;x<12;x++)for(int z=0;z<12;z++){h.setBlock(new BlockPos(x,2,z),Blocks.STONE);h.setBlock(new BlockPos(x,3,z),Blocks.WATER);}var b=boat(h,5,5,Boat.Type.BAMBOO);h.runAtTickTime(60,()->{h.assertTrue(b.isAlive()&&ToxinBoats.exposure(b)==0,"Water corroded raft");b.discard();h.succeed();});}
    @GameTest(template="empty",timeoutTicks=20,batch="hull_seal") public static void openTopHullStaysDryAndSideAndFloorBreachesFloodIt(GameTestHelper h){
        int nx=5,ny=3,nz=7;boolean[] a=new boolean[nx*ny*nz];for(int y=0;y<ny;y++)for(int z=0;z<nz;z++)for(int x=0;x<nx;x++)a[(y*nz+z)*nx+x]=y==0||x==0||x==nx-1||z==0||z==nz-1;
        var dry=HullSeal.enclosed(a,nx,ny,nz);h.assertTrue(dry.cardinality()==30,"Open-top watertight hull must enclose 30 air cells");
        a[(1*nz+3)*nx]=false;h.assertTrue(HullSeal.enclosed(a,nx,ny,nz).isEmpty(),"Side hole did not admit toxin");a[(1*nz+3)*nx]=true;a[3*nx+2]=false;h.assertTrue(HullSeal.enclosed(a,nx,ny,nz).isEmpty(),"Floor hole did not admit toxin");
        a[3*nx+2]=true;a[(2*nz+3)*nx]=false;var lip=HullSeal.enclosed(a,nx,ny,nz);h.assertTrue(lip.cardinality()==15,"High rim breach flooded lower cells before its water level");h.succeed();
    }
    @GameTest(template="empty",timeoutTicks=20,batch="wave_forces") public static void waveBuoyancyCannotPushFullySubmergedOrDryVoxels(GameTestHelper h){for(int i=0;i<1000;i++){double a=.1+i*.05,wave=35+Math.sin(i)*.42;h.assertTrue(SableOceanBridge.volumeDifference(wave,35,30,a)==0,"Wave force pushed a fully submerged voxel");h.assertTrue(SableOceanBridge.volumeDifference(wave,35,40,a)==0,"Wave force acted on a dry voxel");double f=SableOceanBridge.volumeDifference(wave,35,35,a);h.assertTrue(Math.abs(f)<=9.81*a*.42000001,"Volume difference escaped its bound");h.assertTrue(Math.signum(f)==Math.signum(wave-35),"Buoyancy correction reversed");}h.succeed();}
}
